package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.maos.commons.deploy.EnvUtil;
import com.huawei.oss.rest.util.RestCaller;
import com.huawei.oss.rest.util.RestMethod;
import com.huawei.oss.rest.util.RespHeaderMap;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * 实例工具类
 *
 * @since 2025/09/09
 */
public class InstanceUtils {
    private static final OssLog LOGGER = OssLogFactory.getLogger(InstanceUtils.class);

    private static final String POLICY_URL = "/rest/oss/inner/experienceassuranceservice/v1/policy";

    private static final String HEADER_BACKEND_LIST_POLICY = "XX-Backend-List-Policy";

    private static final String HEADER_BACKEND_LIST_VALUE = "instanceOnly";

    private static final String RESPONSE_HEADER_BACKEND_LIST = "Xx-Backend-List";

    private static final String POD_NAME_ENV = "POD_NAME";

    private static final String ALL_PREFIX = "all=";

    private static final String COMMA_SEPARATOR = ",";

    private static final String DASH_SEPARATOR = "-";

    /**
     * 查询所有实例ID
     *
     * @return 所有实例ID列表
     */
    public static List<Integer> queryAllInstanceIds() {
        List<Integer> instanceIds = new ArrayList<>();
        try {
            RespHeaderMap respHeaderMap = new RestCaller.Builder(POLICY_URL, RestMethod.POST)
                .header(HEADER_BACKEND_LIST_POLICY, HEADER_BACKEND_LIST_VALUE)
                .build()
                .call()
                .getRespHeaderMap();
            String backendListValue = respHeaderMap.get(RSPONSE_HEADER_BACKEND_LIST);
            LOGGER.info("Backend list value: {}", backendListValue);
            if (backendListValue == null || !backendListValue.startsWith(ALL_PREFIX)) {
                LOGGER.warn("Backend list value is empty or invalid: {}", backendListValue);
                return instanceIds;
            }
            String instanceList = backendListValue.substring(ALL_PREFIX.length());
            String[] instanceNames = instanceList.split(COMMA_SEPARATOR);
            for (String instanceName : instanceNames) {
                Optional<Integer> instanceId = parseInstanceId(instanceName.trim());
                if (instanceId.isPresent()) {
                    instanceIds.add(instanceId.get());
                }
            }
        } catch (Exception e) {
            LOGGER.error("Query all instance ids failed.", e);
            if (e instanceof ServiceException) {
                throw (ServiceException) e;
            }
        }
        return instanceIds;
    }

    /**
     * 查询当前实例ID
     *
     * @return 当前实例ID
     */
    public static Optional<Integer> queryCurrentInstanceId() {
        String podName = EnvUtil.getEnv(POD_NAME_ENV);
        LOGGER.info("Current pod name: {}", podName);
        if (podName == null || podName.isEmpty()) {
            LOGGER.warn("POD_NAME environment variable is not set.");
            return Optional.empty();
        }
        return parseInstanceId(podName);
    }

    /**
     * 解析实例名称获取整数ID
     *
     * @param instanceName 实例名称，格式如 service-b-1
     * @return 实例ID，解析失败返回Optional.empty()
     */
    private static Optional<Integer> parseInstanceId(String instanceName) {
        try {
            if (instanceName == null || instanceName.isEmpty()) {
                return Optional.empty();
            }
            String[] parts = instanceName.split(DASH_SEPARATOR);
            String lastPart = parts[parts.length - 1];
            int id = Integer.parseInt(lastPart);
            return Optional.of(id);
        } catch (NumberFormatException e) {
            LOGGER.warn("Parse instance id failed for instanceName: {}", instanceName, e);
            return Optional.empty();
        }
    }
}
